head.script:
scwin.vScrenID = "ULDFIS00306.xml";

scwin.onpageload = function() {
    scwin.fn_Init();
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    scwin.fn_Search();
};
/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dlt_ForncurrAsstDebtRes.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.
    scwin.vKisCd = $p.parent().wfm_header.getWindow().scwin.fn_GetKisCd();
    if (scwin.vKisCd == "") {
        return false;
    }
    return true;
};


/**
 * 외화자산/부채 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    const ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue();

    let url = "/api/listing/nice/individual-notes/" + ibxKisCd + "/foreign-currency";
    $c.sbm.setAction(sbm_dlt_ForncurrAsstDebt, url);
    $c.sbm.execute(sbm_dlt_ForncurrAsstDebt);
};


/**
 * 외화자산  팝업
 */
scwin.fn_ForncurrAsstSrchOpen = function(pRow) {
    console.log(pRow);
    let url = "/ui/lst/fis/ULDFIS00300_P3.xml";
    let popTitle = "외화자산 검색";

    const opts = {
        id: "ULDFIS00300_P3",
        popupName: popTitle,
        width: 700,
        height: 500,
        frameModal: "top",
    };

    const popData = dlt_ForncurrAsstDebtRes.getRowJSON(pRow);
    $c.win.openPopup(url, opts, popData);
};


/**
 * 외화부채  팝업
 */
scwin.fn_ForncurrDebtSrchOpen = async function(pRow) {
    console.log(pRow);
    let url = "/ui/lst/fis/ULDFIS00300_P4.xml";
    let popTitle = "외화부채 검색";

    const opts = {
        id: "ULDFIS00300_P4",
        popupName: popTitle,
        width: 700,
        height: 590,
        frameModal: "top",
    };

    const popData = dlt_ForncurrAsstDebtRes.getRowJSON(pRow);
    console.log("rowData :: "  + popData)
    $c.win.openPopup(url, opts, popData);
};


/**
 *  엑셀파일다운로드
 */
scwin.fn_excel_download = function() {
    if (dlt_ForncurrAsstDebtRes.getTotalRow() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_ForncurrAsstDebt, "외화자산부채", "", "8");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};

/**
 *  팝업분기
 */
scwin.grd_ForncurrAsstDebt_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    if (columnId == "valuBas1") {
        // 외화자산  팝업 오픈
        scwin.fn_ForncurrAsstSrchOpen(rowIndex);
    } else if (columnId == "valuBas2") {
        // 외화부채 팝업 오픈
        scwin.fn_ForncurrDebtSrchOpen(rowIndex);
    }
};
